// De-Esser: Suno Studio audio effect (applied to rendered audio, not a lyric tag).
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Band split: g.biquad highpass at 'frequency' isolates the sibilant band; the low band is (trimmed - sibilant).
//   3. Envelope: g.asymmetricOnePole tracks g.abs(sibilant). Attack/release coefs are derived from the
//      'attack'/'release' ms params and config.sampleRate via coef = 1 - 1/(ms/1000 * sampleRate),
//      approximated with confirmed primitives (no exp available, so a one-pole samples-based coef).
//   4. Gain compute: threshold dB -> linear via g.dbToLin. g.compareLt(threshold, env) yields 1 when the
//      envelope is over threshold, else 0. That mask scales the duck amount ('reduction' percent).
//   5. Duck: subtract (mask * reduction * sibilant) from the sibilant band, then recombine with the low band.
//   6. Output gain, then g.tanh safety before g.output.
// LIMITATION: the duck is a HARD gate (binary g.compareLt mask, no soft knee), because the confirmed set has no
// exp/log to build a smooth gain computer. It can produce zipper artifacts; listen-test before relying on it.
// Bypass: g.lerp(bypass, out, trimmed) ASSUMES the 'bypass' enum resolves to 0 ('off') / 1 ('on'), so
// 'off' passes the PROCESSED signal and 'on' passes the DRY signal (see AUTHORING.md).
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var freq = g.input('frequency');
  var threshDb = g.input('threshold');
  var reductionPct = g.input('reduction');
  var attackMs = g.input('attack');
  var releaseMs = g.input('release');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var threshLin = g.dbToLin(threshDb);
  var reduction = g.clamp(g.div(reductionPct, g.constant(100)), g.zero(), g.constant(1));
  var sr = g.constant(config.sampleRate);

  // one-pole coef approximation: coef = clamp(1 - 1/(seconds*sr), 0, 0.9999)
  var attackSec = g.div(attackMs, g.constant(1000));
  var releaseSec = g.div(releaseMs, g.constant(1000));
  var attackSamples = g.max(g.mul(attackSec, sr), g.constant(1));
  var releaseSamples = g.max(g.mul(releaseSec, sr), g.constant(1));
  var attackCoef = g.clamp(g.sub(g.constant(1), g.div(g.constant(1), attackSamples)), g.zero(), g.constant(0.9999));
  var releaseCoef = g.clamp(g.sub(g.constant(1), g.div(g.constant(1), releaseSamples)), g.zero(), g.constant(0.9999));

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var sib = g.biquad({ input: trimmed, cutoff: freq, resonance: g.constant(0.707), mode: 'highpass' });
    var low = g.sub(trimmed, sib);
    var env = g.asymmetricOnePole({ target: g.abs(sib), attackCoef: attackCoef, releaseCoef: releaseCoef });
    var over = g.compareLt(threshLin, env);
    var duckAmt = g.mul(over, reduction);
    var ducked = g.sub(sib, g.mul(sib, duckAmt));
    var recombined = g.add(low, ducked);
    var out = g.mul(recombined, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
